"""SQLAlchemy ORM models for application data.

All application tables live in the ``coach`` PostgreSQL schema. LangGraph's
checkpoint tables (Phase 4) will live in the separate ``langgraph`` schema and
are never declared here.

Conventions
-----------
* Primary keys: ``BIGINT GENERATED BY DEFAULT AS IDENTITY``.
* Timestamps: ``timestamptz`` stored in UTC. Training "days" are ``date``
  columns interpreted in the athlete's local timezone.
* Status/category columns: ``text`` + ``CHECK`` constraint (easier to evolve
  with Alembic than native PG enums).
* Raw third-party payloads are kept verbatim in ``JSONB`` (``raw_payload``) so
  normalised columns can be re-derived later without re-fetching.
* Units are encoded in column names (``_watts``, ``_s``, ``_m``, ``_kg``...).
"""

from __future__ import annotations

import datetime as dt
from typing import Any

from sqlalchemy import (
    BigInteger,
    Boolean,
    CheckConstraint,
    Date,
    DateTime,
    Float,
    ForeignKey,
    Identity,
    Index,
    Integer,
    MetaData,
    Text,
    UniqueConstraint,
    func,
    text,
)
from sqlalchemy.dialects.postgresql import JSONB
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column

APP_SCHEMA = "coach"
LANGGRAPH_SCHEMA = "langgraph"

NAMING_CONVENTION = {
    "ix": "ix_%(table_name)s_%(column_0_N_name)s",
    "uq": "uq_%(table_name)s_%(column_0_N_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}

# --- Allowed values for CHECK constraints ------------------------------------
EXPERIENCE_LEVELS = ("beginner", "intermediate", "advanced", "elite")
TRAINING_PLAN_STATUSES = ("draft", "active", "completed", "archived")
PLANNED_WORKOUT_STATUSES = (
    "draft",  # generated, not yet validated
    "validated",  # passed deterministic validation
    "rejected",  # failed validation; never published
    "published",  # on the Intervals.icu calendar
    "completed",  # matched to a completed activity
    "missed",  # day passed without a matching activity
    "skipped",  # deliberately skipped by athlete/coach
    "superseded",  # replaced by a newer plan for the same day
    "cancelled",  # withdrawn
)
# Workouts in these states do not count toward the "one workout per day" rule.
INACTIVE_WORKOUT_STATUSES = ("rejected", "superseded", "cancelled")
PERFORMANCE_OUTCOMES = (
    "as_planned",
    "completed_with_deviation",
    "partial",
    "abandoned",
    "unplanned",
)
WEBHOOK_STATUSES = ("received", "processing", "processed", "failed", "ignored")
PUBLISH_ACTIONS = ("create", "update", "delete", "verify", "skip")
SYNC_CHECK_STATUSES = (
    "verified",  # observed in synchronized data
    "confirmed",  # confirmed manually by the athlete (not observable through the API)
    "configured",  # enabled in Intervals.icu settings, but not observable through the API
    "not_observed",  # enabled, but no evidence in the data yet
    "not_configured",  # integration or direction not enabled
    "attention",  # evidence of a problem (e.g. duplicate recordings)
)


def _in_check(column: str, values: tuple[str, ...]) -> str:
    quoted = ", ".join(f"'{v}'" for v in values)
    return f"{column} IN ({quoted})"


class Base(DeclarativeBase):
    metadata = MetaData(schema=APP_SCHEMA, naming_convention=NAMING_CONVENTION)
    type_annotation_map = {dict[str, Any]: JSONB, list[Any]: JSONB}  # noqa: RUF012 (SQLAlchemy API)


class TimestampMixin:
    created_at: Mapped[dt.datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now(), nullable=False
    )
    updated_at: Mapped[dt.datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now(), onupdate=func.now(), nullable=False
    )


def _pk() -> Mapped[int]:
    return mapped_column(BigInteger, Identity(always=False), primary_key=True)


def _athlete_fk() -> Mapped[int]:
    return mapped_column(
        BigInteger, ForeignKey("athlete_profile.id", ondelete="CASCADE"), nullable=False
    )


_EMPTY_JSON_OBJECT = text("'{}'::jsonb")


class AthleteProfile(TimestampMixin, Base):
    """The athlete and their (mutable) physiological and preference settings."""

    __tablename__ = "athlete_profile"
    __table_args__ = (
        UniqueConstraint("slug"),
        UniqueConstraint("intervals_athlete_id"),
        CheckConstraint("ftp_watts IS NULL OR (ftp_watts > 0 AND ftp_watts <= 600)", name="ftp"),
        CheckConstraint(
            "weight_kg IS NULL OR (weight_kg > 20 AND weight_kg <= 250)", name="weight"
        ),
        CheckConstraint(
            "height_cm IS NULL OR (height_cm > 100 AND height_cm <= 250)", name="height"
        ),
        CheckConstraint(_in_check("experience_level", EXPERIENCE_LEVELS), name="experience"),
    )

    id: Mapped[int] = _pk()
    slug: Mapped[str] = mapped_column(Text, nullable=False)
    display_name: Mapped[str] = mapped_column(Text, nullable=False)
    intervals_athlete_id: Mapped[str | None] = mapped_column(Text)
    # FTP may be NULL (unknown). Publishing logic must refuse to publish without it.
    ftp_watts: Mapped[int | None] = mapped_column(Integer)
    ftp_updated_at: Mapped[dt.datetime | None] = mapped_column(DateTime(timezone=True))
    weight_kg: Mapped[float | None] = mapped_column(Float)
    height_cm: Mapped[float | None] = mapped_column(Float)
    age_years: Mapped[int | None] = mapped_column(Integer)
    date_of_birth: Mapped[dt.date | None] = mapped_column(Date)
    experience_level: Mapped[str] = mapped_column(Text, nullable=False)
    primary_objective: Mapped[str | None] = mapped_column(Text)
    secondary_objective: Mapped[str | None] = mapped_column(Text)
    timezone: Mapped[str] = mapped_column(Text, nullable=False)
    indoor_platform: Mapped[str | None] = mapped_column(Text)
    wearable: Mapped[str | None] = mapped_column(Text)
    availability: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )
    preferences: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )
    # Last athlete object fetched from Intervals.icu (secrets redacted). Kept as a
    # reference only: the columns above stay authoritative (see docs/INTERVALS_ICU.md).
    intervals_snapshot: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )
    intervals_synced_at: Mapped[dt.datetime | None] = mapped_column(DateTime(timezone=True))


class Activity(TimestampMixin, Base):
    """A completed activity imported from a source platform (Intervals.icu)."""

    __tablename__ = "activities"
    __table_args__ = (
        UniqueConstraint("source", "source_activity_id"),
        Index("ix_activities_athlete_id_start_time", "athlete_id", "start_time"),
        Index("ix_activities_athlete_id_start_date_local", "athlete_id", "start_date_local"),
    )

    id: Mapped[int] = _pk()
    athlete_id: Mapped[int] = _athlete_fk()
    source: Mapped[str] = mapped_column(Text, nullable=False)
    source_activity_id: Mapped[str] = mapped_column(Text, nullable=False)
    start_time: Mapped[dt.datetime] = mapped_column(DateTime(timezone=True), nullable=False)
    start_date_local: Mapped[dt.date] = mapped_column(Date, nullable=False)
    activity_type: Mapped[str | None] = mapped_column(Text)
    name: Mapped[str | None] = mapped_column(Text)
    is_indoor: Mapped[bool | None] = mapped_column(Boolean)
    moving_time_s: Mapped[int | None] = mapped_column(Integer)
    elapsed_time_s: Mapped[int | None] = mapped_column(Integer)
    distance_m: Mapped[float | None] = mapped_column(Float)
    elevation_gain_m: Mapped[float | None] = mapped_column(Float)
    avg_power_watts: Mapped[float | None] = mapped_column(Float)
    normalized_power_watts: Mapped[float | None] = mapped_column(Float)
    avg_hr_bpm: Mapped[float | None] = mapped_column(Float)
    max_hr_bpm: Mapped[float | None] = mapped_column(Float)
    ftp_at_activity_watts: Mapped[int | None] = mapped_column(Integer)
    # Values reported by the source; our own deterministic values go in training_metrics.
    source_training_load: Mapped[float | None] = mapped_column(Float)
    source_intensity_factor: Mapped[float | None] = mapped_column(Float)
    rpe: Mapped[float | None] = mapped_column(Float)
    feel: Mapped[int | None] = mapped_column(Integer)
    # Provenance (Phase 6, migration 0004): how the activity reached Intervals.icu.
    origin: Mapped[str | None] = mapped_column(Text)  # Intervals.icu "source", e.g. COROS
    origin_client: Mapped[str | None] = mapped_column(Text)  # "oauth_client_name"
    device_name: Mapped[str | None] = mapped_column(Text)
    origin_external_id: Mapped[str | None] = mapped_column(Text)  # "external_id"
    paired_event_id: Mapped[str | None] = mapped_column(Text)  # planned event it was paired with
    # Set when the same ride was recorded twice (e.g. trainer app + watch);
    # duplicates are excluded from training load.
    duplicate_of_activity_id: Mapped[int | None] = mapped_column(
        BigInteger, ForeignKey("activities.id", ondelete="SET NULL")
    )
    raw_payload: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )


class DailyRecovery(TimestampMixin, Base):
    """Daily wellness/recovery record for one athlete, one day, one source."""

    __tablename__ = "daily_recovery"
    __table_args__ = (UniqueConstraint("athlete_id", "recovery_date", "source"),)

    id: Mapped[int] = _pk()
    athlete_id: Mapped[int] = _athlete_fk()
    recovery_date: Mapped[dt.date] = mapped_column(Date, nullable=False)
    source: Mapped[str] = mapped_column(Text, nullable=False)
    resting_hr_bpm: Mapped[float | None] = mapped_column(Float)
    hrv_rmssd_ms: Mapped[float | None] = mapped_column(Float)
    sleep_duration_s: Mapped[int | None] = mapped_column(Integer)
    sleep_score: Mapped[float | None] = mapped_column(Float)
    subjective_fatigue: Mapped[int | None] = mapped_column(Integer)
    subjective_soreness: Mapped[int | None] = mapped_column(Integer)
    subjective_stress: Mapped[int | None] = mapped_column(Integer)
    # Intervals.icu "injury" (1 none, 2 niggle, 3 poor, 4 injured; see TRAINING_ENGINE.md).
    subjective_injury: Mapped[int | None] = mapped_column(Integer)
    illness_reported: Mapped[bool] = mapped_column(
        Boolean, server_default=text("false"), nullable=False
    )
    pain_reported: Mapped[bool] = mapped_column(
        Boolean, server_default=text("false"), nullable=False
    )
    notes: Mapped[str | None] = mapped_column(Text)
    raw_payload: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )


class CalendarEvent(TimestampMixin, Base):
    """An event on the athlete's Intervals.icu calendar (planned workout, note, …).

    Mirrors the source calendar, including events not created by the coach, so
    later phases never plan against an unknown calendar. Events that disappear
    from a re-fetched window are soft-deleted (``deleted_at``), not removed.
    """

    __tablename__ = "calendar_events"
    __table_args__ = (
        UniqueConstraint("source", "source_event_id"),
        Index("ix_calendar_events_athlete_id_start_date_local", "athlete_id", "start_date_local"),
        Index("ix_calendar_events_external_id", "external_id"),
    )

    id: Mapped[int] = _pk()
    athlete_id: Mapped[int] = _athlete_fk()
    source: Mapped[str] = mapped_column(Text, nullable=False)
    source_event_id: Mapped[str] = mapped_column(Text, nullable=False)
    category: Mapped[str] = mapped_column(Text, nullable=False)
    event_type: Mapped[str | None] = mapped_column(Text)
    start_date_local: Mapped[dt.date] = mapped_column(Date, nullable=False)
    start_time_local: Mapped[dt.datetime | None] = mapped_column(DateTime(timezone=False))
    end_date_local: Mapped[dt.date | None] = mapped_column(Date)
    name: Mapped[str | None] = mapped_column(Text)
    description: Mapped[str | None] = mapped_column(Text)
    external_id: Mapped[str | None] = mapped_column(Text)
    is_indoor: Mapped[bool | None] = mapped_column(Boolean)
    planned_duration_s: Mapped[int | None] = mapped_column(Integer)
    planned_training_load: Mapped[float | None] = mapped_column(Float)
    source_updated_at: Mapped[dt.datetime | None] = mapped_column(DateTime(timezone=True))
    deleted_at: Mapped[dt.datetime | None] = mapped_column(DateTime(timezone=True))
    raw_payload: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )


class TrainingPlan(TimestampMixin, Base):
    """Long-term plan (macro/meso cycle structure) toward an objective."""

    __tablename__ = "training_plans"
    __table_args__ = (
        CheckConstraint(_in_check("status", TRAINING_PLAN_STATUSES), name="status"),
        CheckConstraint("end_date IS NULL OR end_date >= start_date", name="dates"),
        # At most one active plan per athlete.
        Index(
            "uq_training_plans_one_active_per_athlete",
            "athlete_id",
            unique=True,
            postgresql_where=text("status = 'active'"),
        ),
    )

    id: Mapped[int] = _pk()
    athlete_id: Mapped[int] = _athlete_fk()
    name: Mapped[str] = mapped_column(Text, nullable=False)
    objective: Mapped[str] = mapped_column(Text, nullable=False)
    start_date: Mapped[dt.date] = mapped_column(Date, nullable=False)
    end_date: Mapped[dt.date | None] = mapped_column(Date)
    status: Mapped[str] = mapped_column(Text, server_default=text("'draft'"), nullable=False)
    phases: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )
    plan_metadata: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )


class CoachDecision(Base):
    """An auditable coaching decision (deterministic inputs + LLM output)."""

    __tablename__ = "coach_decisions"
    __table_args__ = (
        Index("ix_coach_decisions_athlete_id_decision_date", "athlete_id", "decision_date"),
        Index("ix_coach_decisions_graph_thread_id", "graph_thread_id"),
    )

    id: Mapped[int] = _pk()
    athlete_id: Mapped[int] = _athlete_fk()
    decision_date: Mapped[dt.date] = mapped_column(Date, nullable=False)
    decision_type: Mapped[str] = mapped_column(Text, nullable=False)
    graph_thread_id: Mapped[str | None] = mapped_column(Text)
    graph_run_id: Mapped[str | None] = mapped_column(Text)
    model_name: Mapped[str | None] = mapped_column(Text)
    prompt_version: Mapped[str | None] = mapped_column(Text)
    input_snapshot: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )
    output: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )
    rationale: Mapped[str | None] = mapped_column(Text)
    created_at: Mapped[dt.datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now(), nullable=False
    )


class PlannedWorkout(TimestampMixin, Base):
    """A workout planned by the coach for a given local date."""

    __tablename__ = "planned_workouts"
    __table_args__ = (
        UniqueConstraint("external_id"),
        UniqueConstraint("intervals_event_id"),
        CheckConstraint(_in_check("status", PLANNED_WORKOUT_STATUSES), name="status"),
        CheckConstraint(
            "ftp_reference_watts IS NULL OR ftp_reference_watts > 0", name="ftp_reference"
        ),
        CheckConstraint("planned_duration_s IS NULL OR planned_duration_s >= 0", name="duration"),
        # One live workout per athlete per day (rest days count as a workout row).
        Index(
            "uq_planned_workouts_one_active_per_day",
            "athlete_id",
            "workout_date",
            unique=True,
            postgresql_where=text(
                "status NOT IN (" + ", ".join(f"'{s}'" for s in INACTIVE_WORKOUT_STATUSES) + ")"
            ),
        ),
        Index("ix_planned_workouts_athlete_id_workout_date", "athlete_id", "workout_date"),
    )

    id: Mapped[int] = _pk()
    athlete_id: Mapped[int] = _athlete_fk()
    training_plan_id: Mapped[int | None] = mapped_column(
        BigInteger, ForeignKey("training_plans.id", ondelete="SET NULL")
    )
    coach_decision_id: Mapped[int | None] = mapped_column(
        BigInteger, ForeignKey("coach_decisions.id", ondelete="SET NULL")
    )
    workout_date: Mapped[dt.date] = mapped_column(Date, nullable=False)
    # Stable idempotency key used when publishing to Intervals.icu.
    external_id: Mapped[str] = mapped_column(Text, nullable=False)
    intervals_event_id: Mapped[str | None] = mapped_column(Text)
    status: Mapped[str] = mapped_column(Text, server_default=text("'draft'"), nullable=False)
    workout_type: Mapped[str] = mapped_column(Text, nullable=False)
    name: Mapped[str] = mapped_column(Text, nullable=False)
    objective: Mapped[str | None] = mapped_column(Text)
    planned_duration_s: Mapped[int | None] = mapped_column(Integer)
    planned_training_load: Mapped[float | None] = mapped_column(Float)
    ftp_reference_watts: Mapped[int | None] = mapped_column(Integer)
    structure: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )
    validation_result: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )
    published_at: Mapped[dt.datetime | None] = mapped_column(DateTime(timezone=True))


class WorkoutPerformance(TimestampMixin, Base):
    """Planned-vs-actual evaluation for one completed activity."""

    __tablename__ = "workout_performance"
    __table_args__ = (
        UniqueConstraint("activity_id"),
        Index("ix_workout_performance_planned_workout_id", "planned_workout_id"),
        CheckConstraint(
            "completion_pct IS NULL OR (completion_pct >= 0 AND completion_pct <= 200)",
            name="completion",
        ),
        CheckConstraint(
            "outcome IS NULL OR " + _in_check("outcome", PERFORMANCE_OUTCOMES), name="outcome"
        ),
        Index("ix_workout_performance_athlete_id", "athlete_id"),
    )

    id: Mapped[int] = _pk()
    athlete_id: Mapped[int] = _athlete_fk()
    activity_id: Mapped[int] = mapped_column(
        BigInteger, ForeignKey("activities.id", ondelete="CASCADE"), nullable=False
    )
    planned_workout_id: Mapped[int | None] = mapped_column(
        BigInteger, ForeignKey("planned_workouts.id", ondelete="SET NULL")
    )
    completion_pct: Mapped[float | None] = mapped_column(Float)
    power_deviation_pct: Mapped[float | None] = mapped_column(Float)
    hr_response: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )
    step_compliance: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )
    rpe: Mapped[float | None] = mapped_column(Float)
    evaluation: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )
    calculation_version: Mapped[str | None] = mapped_column(Text)
    # Phase 7 (migration 0005)
    outcome: Mapped[str | None] = mapped_column(Text)
    decoupling_pct: Mapped[float | None] = mapped_column(Float)
    session_date: Mapped[dt.date | None] = mapped_column(Date)  # activity's local date
    # Hash of the activity fields the evaluation used; a change re-triggers it.
    activity_revision: Mapped[str | None] = mapped_column(Text)


class TrainingMetric(TimestampMixin, Base):
    """Deterministic daily training-load metrics (CTL/ATL/TSB etc.)."""

    __tablename__ = "training_metrics"
    __table_args__ = (UniqueConstraint("athlete_id", "metric_date", "calculation_version"),)

    id: Mapped[int] = _pk()
    athlete_id: Mapped[int] = _athlete_fk()
    metric_date: Mapped[dt.date] = mapped_column(Date, nullable=False)
    calculation_version: Mapped[str] = mapped_column(Text, nullable=False)
    daily_tss: Mapped[float | None] = mapped_column(Float)
    ctl: Mapped[float | None] = mapped_column(Float)
    atl: Mapped[float | None] = mapped_column(Float)
    tsb: Mapped[float | None] = mapped_column(Float)
    rolling_7d_tss: Mapped[float | None] = mapped_column(Float)
    # Fraction (0..1) of the look-back window with usable data. Below a threshold,
    # metrics must not be presented as authoritative.
    data_completeness: Mapped[float | None] = mapped_column(Float)
    details: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )


class SynchronizationState(Base):
    """Incremental sync cursor per athlete/source/resource."""

    __tablename__ = "synchronization_state"
    __table_args__ = (UniqueConstraint("athlete_id", "source", "resource"),)

    id: Mapped[int] = _pk()
    athlete_id: Mapped[int] = _athlete_fk()
    source: Mapped[str] = mapped_column(Text, nullable=False)
    resource: Mapped[str] = mapped_column(Text, nullable=False)
    cursor: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )
    last_attempt_at: Mapped[dt.datetime | None] = mapped_column(DateTime(timezone=True))
    last_success_at: Mapped[dt.datetime | None] = mapped_column(DateTime(timezone=True))
    last_error: Mapped[str | None] = mapped_column(Text)
    consecutive_failures: Mapped[int] = mapped_column(
        Integer, server_default=text("0"), nullable=False
    )
    updated_at: Mapped[dt.datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now(), onupdate=func.now(), nullable=False
    )


class WebhookEvent(Base):
    """Inbound webhook events, deduplicated by ``(source, dedup_key)``."""

    __tablename__ = "webhook_events"
    __table_args__ = (
        UniqueConstraint("source", "dedup_key"),
        CheckConstraint(_in_check("status", WEBHOOK_STATUSES), name="status"),
        Index("ix_webhook_events_status_received_at", "status", "received_at"),
    )

    id: Mapped[int] = _pk()
    source: Mapped[str] = mapped_column(Text, nullable=False)
    dedup_key: Mapped[str] = mapped_column(Text, nullable=False)
    event_type: Mapped[str | None] = mapped_column(Text)
    payload: Mapped[dict[str, Any]] = mapped_column(
        server_default=_EMPTY_JSON_OBJECT, nullable=False
    )
    status: Mapped[str] = mapped_column(Text, server_default=text("'received'"), nullable=False)
    attempts: Mapped[int] = mapped_column(Integer, server_default=text("0"), nullable=False)
    last_error: Mapped[str | None] = mapped_column(Text)
    received_at: Mapped[dt.datetime] = mapped_column(
        DateTime(timezone=True), server_default=func.now(), nullable=False
    )
    processed_at: Mapped[dt.datetime | None] = mapped_column(DateTime(timezone=True))


class PublishingAudit(Base):
    """Append-only audit trail of every publish attempt (successful or not)."""

    __tablename__ = "publishing_audit"
    __table_args__ = (
        CheckConstraint(_in_check("action", PUBLISH_ACTIONS), name="action"),
        Index("ix_publishing_audit_planned_workout_id", "planned_workout_id"),
        Index("ix_publishing_audit_athlete_id_created_at", "athlete_id", "created_at"),
    )

    id: Mapped[int] = _pk()
    # RESTRICT: audit rows must never silently disappear with their athlete/workout.
    # The table is also append-only (UPDATE/DELETE blocked by a trigger, see migration 0001).
    athlete_id: Mapped[int] = mapped_column(
        BigInteger, ForeignKey("athlete_profile.id", ondelete="RESTRICT"), nullable=False
    )
    planned_workout_id: Mapped[int | None] = mapped_column(
        BigInteger, ForeignKey("planned_workouts.id", ondelete="RESTRICT")
    )
    action: Mapped[str] = mapped_column(Text, nullable=False)
